// Copyright 2014 Manu Martinez-Almeida.  All rights reserved.
// Use of this source code is governed by a MIT style
// license that can be found in the LICENSE file.

package binding

import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"time"

	"github.com/gin-gonic/gin/internal/json"
)

var errUnknownType = errors.New("Unknown type")

func mapUri(ptr interface{}, m map[string][]string) error {
	return mapFormByTag(ptr, m, "uri")
}

func mapForm(ptr interface{}, form map[string][]string) error {
	return mapFormByTag(ptr, form, "form")
}

var emptyField = reflect.StructField{}

func mapFormByTag(ptr interface{}, form map[string][]string, tag string) error {
	return mappingByPtr(ptr, formSource(form), tag)
}

// setter tries to set value on a walking by fields of a struct
type setter interface {
	TrySet(value reflect.Value, field reflect.StructField, key string, opt setOptions) (isSetted bool, err error)
}

type formSource map[string][]string

var _ setter = formSource(nil)

// TrySet tries to set a value by request's form source (like map[string][]string)
func (form formSource) TrySet(value reflect.Value, field reflect.StructField, tagValue string, opt setOptions) (isSetted bool, err error) {
	return setByForm(value, field, form, tagValue, opt)
}

func mappingByPtr(ptr interface{}, setter setter, tag string) error {
	_, err := mapping(reflect.ValueOf(ptr), emptyField, setter, tag)
	return err
}

func mapping(value reflect.Value, field reflect.StructField, setter setter, tag string) (bool, error) {
	vKind := value.Kind()
	rootName := field.Name
	rootType := field.Type
	rootAnonymous := field.Anonymous
	rootField := rootName == "" && rootType == nil && !rootAnonymous
	mappingTag := tag
	currentSetter := setter

	if vKind == reflect.Ptr {
		isNew := false
		vPtr := value
		ptrType := value.Type()
		if value.IsNil() {
			isNew = true
			elemType := ptrType.Elem()
			vPtr = reflect.New(elemType)
		}
		elem := vPtr.Elem()
		isSetted, err := mapping(elem, field, currentSetter, mappingTag)
		if err != nil {
			return false, err
		}
		if isNew {
			if isSetted {
				value.Set(vPtr)
			}
		}
		if rootField {
			activeValidator := Validator
			if activeValidator != nil {
				obj := value.Interface()
				if v, ok := activeValidator.(*defaultValidator); ok {
					rv := reflect.ValueOf(obj)
					rk := rv.Kind()
					if rk == reflect.Ptr {
						elemVal := rv.Elem()
						rk = elemVal.Kind()
					}
					if rk == reflect.Struct {
						v.lazyinit()
						engine := v.validate
						if err := engine.Struct(obj); err != nil {
							return false, err
						}
					}
				} else if err := activeValidator.ValidateStruct(obj); err != nil {
					return false, err
				}
			}
		}
		return isSetted, nil
	}

	if vKind != reflect.Struct || !field.Anonymous {
		rawTag := field.Tag.Get(mappingTag)
		tagValue := rawTag
		opts := ""
		if comma := strings.Index(tagValue, ","); comma >= 0 {
			opts = tagValue[comma+1:]
			tagValue = tagValue[:comma]
		} else {
			opts = ""
		}
		ignoreField := tagValue == "-"
		if !ignoreField {
			if tagValue == "" {
				tagValue = field.Name
			}
			hasName := tagValue != ""
			if hasName {
				var setOpt setOptions
				remaining := opts
				for len(remaining) > 0 {
					opt := remaining
					if comma := strings.Index(remaining, ","); comma >= 0 {
						opt = remaining[:comma]
						remaining = remaining[comma+1:]
					} else {
						remaining = ""
					}
					key := opt
					val := ""
					if eq := strings.Index(opt, "="); eq >= 0 {
						key = opt[:eq]
						val = opt[eq+1:]
					}
					optionKey := key
					optionVal := val
					if optionKey == "default" {
						setOpt.isDefaultExists = true
						setOpt.defaultValue = optionVal
					}
				}
				var ok bool
				var err error
				switch s := currentSetter.(type) {
				case formSource:
					ok, err = s.TrySet(value, field, tagValue, setOpt)
				case *multipartRequest:
					ok, err = s.TrySet(value, field, tagValue, setOpt)
				default:
					ok, err = currentSetter.TrySet(value, field, tagValue, setOpt)
				}
				if err != nil {
					return false, err
				}
				if ok {
					return true, nil
				}
			}
		}
	}

	if vKind == reflect.Struct {
		tValue := value.Type()
		numFields := value.NumField()
		structFields := numFields
		var isSetted bool
		for i := 0; i < structFields; i++ {
			fieldIndex := i
			sf := tValue.Field(fieldIndex)
			exported := sf.PkgPath == ""
			if !exported {
				if !sf.Anonymous {
					continue
				}
			}
			fv := value.Field(fieldIndex)
			kind := fv.Kind()
			nestedField := sf
			nestedValue := fv
			var ok bool
			var err error
			switch kind {
			case reflect.Ptr, reflect.Struct, reflect.Slice, reflect.Array, reflect.Map:
				ok, err = mapping(nestedValue, nestedField, currentSetter, mappingTag)
			case reflect.Bool, reflect.String, reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
				reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Float32, reflect.Float64:
				ok, err = mapping(nestedValue, nestedField, currentSetter, mappingTag)
			default:
				ok, err = mapping(nestedValue, nestedField, currentSetter, mappingTag)
			}
			if err != nil {
				return false, err
			}
			if ok {
				isSetted = true
			}
		}
		return isSetted, nil
	}

	return false, nil
}

type setOptions struct {
	isDefaultExists bool
	defaultValue    string
}

func setByForm(value reflect.Value, field reflect.StructField, form map[string][]string, tagValue string, opt setOptions) (isSetted bool, err error) {
	vs, ok := form[tagValue]
	if !ok && !opt.isDefaultExists {
		return false, nil
	}

	switch value.Kind() {
	case reflect.Slice:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		return true, setSlice(vs, value, field)
	case reflect.Array:
		if !ok {
			vs = []string{opt.defaultValue}
		}
		if len(vs) != value.Len() {
			return false, fmt.Errorf("%q is not valid value for %s", vs, value.Type().String())
		}
		return true, setArray(vs, value, field)
	default:
		var val string
		if !ok {
			val = opt.defaultValue
		}

		if len(vs) > 0 {
			val = vs[0]
		}
		return true, setWithProperType(val, value, field)
	}
}

func setWithProperType(val string, value reflect.Value, field reflect.StructField) error {
	switch value.Kind() {
	case reflect.Int:
		return setIntField(val, 0, value)
	case reflect.Int8:
		return setIntField(val, 8, value)
	case reflect.Int16:
		return setIntField(val, 16, value)
	case reflect.Int32:
		return setIntField(val, 32, value)
	case reflect.Int64:
		switch value.Interface().(type) {
		case time.Duration:
			return setTimeDuration(val, value, field)
		}
		return setIntField(val, 64, value)
	case reflect.Uint:
		return setUintField(val, 0, value)
	case reflect.Uint8:
		return setUintField(val, 8, value)
	case reflect.Uint16:
		return setUintField(val, 16, value)
	case reflect.Uint32:
		return setUintField(val, 32, value)
	case reflect.Uint64:
		return setUintField(val, 64, value)
	case reflect.Bool:
		return setBoolField(val, value)
	case reflect.Float32:
		return setFloatField(val, 32, value)
	case reflect.Float64:
		return setFloatField(val, 64, value)
	case reflect.String:
		value.SetString(val)
	case reflect.Struct:
		switch value.Interface().(type) {
		case time.Time:
			return setTimeField(val, field, value)
		}
		return json.Unmarshal([]byte(val), value.Addr().Interface())
	case reflect.Map:
		return json.Unmarshal([]byte(val), value.Addr().Interface())
	default:
		return errUnknownType
	}
	return nil
}

func setIntField(val string, bitSize int, field reflect.Value) error {
	if val == "" {
		val = "0"
	}
	intVal, err := strconv.ParseInt(val, 10, bitSize)
	if err == nil {
		field.SetInt(intVal)
	}
	return err
}

func setUintField(val string, bitSize int, field reflect.Value) error {
	if val == "" {
		val = "0"
	}
	uintVal, err := strconv.ParseUint(val, 10, bitSize)
	if err == nil {
		field.SetUint(uintVal)
	}
	return err
}

func setBoolField(val string, field reflect.Value) error {
	if val == "" {
		val = "false"
	}
	boolVal, err := strconv.ParseBool(val)
	if err == nil {
		field.SetBool(boolVal)
	}
	return err
}

func setFloatField(val string, bitSize int, field reflect.Value) error {
	if val == "" {
		val = "0.0"
	}
	floatVal, err := strconv.ParseFloat(val, bitSize)
	if err == nil {
		field.SetFloat(floatVal)
	}
	return err
}

func setTimeField(val string, structField reflect.StructField, value reflect.Value) error {
	timeFormat := structField.Tag.Get("time_format")
	if timeFormat == "" {
		timeFormat = time.RFC3339
	}

	if val == "" {
		value.Set(reflect.ValueOf(time.Time{}))
		return nil
	}

	l := time.Local
	if isUTC, _ := strconv.ParseBool(structField.Tag.Get("time_utc")); isUTC {
		l = time.UTC
	}

	if locTag := structField.Tag.Get("time_location"); locTag != "" {
		loc, err := time.LoadLocation(locTag)
		if err != nil {
			return err
		}
		l = loc
	}

	t, err := time.ParseInLocation(timeFormat, val, l)
	if err != nil {
		return err
	}

	value.Set(reflect.ValueOf(t))
	return nil
}

func setArray(vals []string, value reflect.Value, field reflect.StructField) error {
	for i, s := range vals {
		err := setWithProperType(s, value.Index(i), field)
		if err != nil {
			return err
		}
	}
	return nil
}

func setSlice(vals []string, value reflect.Value, field reflect.StructField) error {
	slice := reflect.MakeSlice(value.Type(), len(vals), len(vals))
	err := setArray(vals, slice, field)
	if err != nil {
		return err
	}
	value.Set(slice)
	return nil
}

func setTimeDuration(val string, value reflect.Value, field reflect.StructField) error {
	d, err := time.ParseDuration(val)
	if err != nil {
		return err
	}
	value.Set(reflect.ValueOf(d))
	return nil
}

